# master's programs to include (institutes without bachelor programs)
MAG_SELECT = {'03.04.01':'phmath','49.04.01':'ifkst','15.04.03':'pish','27.04.03':'pish','27.04.06':'pish'}

def clean(s):
    return s.strip().strip('«»').strip()

# build directions from source
directions = []
seen = {}
for r in prog:
    code = r['code']
    lvl = code.split('.')[1]
    insts = []
    for i in r['institutes']:
        iid = INST_NAME2ID.get(i['name'])
        if iid and iid not in insts:
            insts.append(iid)
    if code == '40.05.03':
        insts = ['gi']
    if lvl == '02':
        continue  # SPO
    if lvl == '04':
        if code not in MAG_SELECT:
            continue
        if MAG_SELECT[code] not in insts:
            continue
        insts = [MAG_SELECT[code]]
    if code not in DIR:
        continue
    if not insts:
        continue
    desc, discs, roles = DIR[code]
    profiles = [clean(p) for p in r['profiles']]
    level = {'03':'bak','04':'mag','05':'spec'}[lvl]
    key = code
    if key in seen:
        # merge institutes (14.05.02)
        d = seen[key]
        for x in insts:
            if x not in d['inst']:
                d['inst'].append(x)
        for p in profiles:
            if p not in d['profiles']:
                d['profiles'].append(p)
        continue
    d = dict(id='d'+code.replace('.',''), code=code, name=r['name'], level=level,
             inst=insts, profiles=profiles, desc=desc, disc=discs, roles=roles,
             url='https://dep.spbstu.ru/edu/'+code+'/')
    seen[key] = d
    directions.append(d)

# disciplines list (only used)
used_disc = set()
for d in directions:
    used_disc.update(d['disc'])
disciplines = [dict(id=k, name=v[0], area=v[1], desc=v[2]) for k, v in DISC.items() if k in used_disc]

roles = [dict(id=k, name=v[0], field=v[1], desc=v[2], salary=v[3], skills=v[4]) for k, v in ROLES.items()]
companies = [dict(id=c[0], name=c[1], sector=c[2], status=c[3], desc=c[4], note=c[5], roles=c[6], url=c[7]) for c in COMPANIES]

# validate references
errs = []
dids = {d['id'] for d in directions}
discids = {d['id'] for d in disciplines}
roleids = {r['id'] for r in roles}
for d in directions:
    for x in d['disc']:
        if x not in discids: errs.append(('disc', d['code'], x))
    for x in d['roles']:
        if x not in roleids: errs.append(('role', d['code'], x))
for c in companies:
    for x in c['roles']:
        if x not in roleids: errs.append(('crole', c['id'], x))
iids = {i['id'] for i in INSTITUTES}
for d in directions:
    for x in d['inst']:
        if x not in iids: errs.append(('inst', d['code'], x))
if errs:
    print('REFERENCE ERRORS:', errs)
    raise SystemExit(1)

